import {nailSilhouette} from './nail-icons.js';
import {previewCanvas} from './objects.js';
// Layout owns viewport dimensions; camera navigation remains user-owned.
export function createWorkbenchLayout(root,center,open,close){
 const source=root.querySelector('.table-objects'),tools=source.querySelector('.tools'),transfer=source.querySelector('.transfer-entry');
 const bench=document.createElement('section');bench.id='workbench';bench.setAttribute('aria-label','Nail toolbox');
 const toggle=document.createElement('button');toggle.id='toolbox-case';toggle.setAttribute('aria-label','Open nail toolbox');toggle.innerHTML='<svg viewBox="0 0 290 100" aria-hidden="true"><path class="case-body" d="M19 36 Q143 31 271 37 L266 83 Q141 90 23 83Z"/><g class="case-lid"><path d="M19 36 L30 16 Q145 10 260 17 L271 37 Q145 45 19 36Z"/><path d="M115 15 L117 5 Q145 0 174 5 L175 15" fill="none"/></g><path d="M52 40v9h17v-9 M221 40v9h17v-9 M136 42v14h18V42" fill="#d3c1a3"/><path d="M31 76 Q145 82 258 76" fill="none" opacity=".35"/></svg><span>NAIL TOOLBOX ↗</span>';toggle.onclick=()=>open('home');
 const nav=document.createElement('nav');nav.id='workbench-nav';nav.setAttribute('aria-label','Toolbox compartments');
 for(const [key,label] of [['color','POLISH'],['nail','NAILS'],['objects','CHARMS'],['tools','TOOLS']]){const b=document.createElement('button');b.className='compartment';b.setAttribute('aria-label',label);b.dataset.section=key;b.innerHTML='<span>'+label+'</span><span class="compartment-art" aria-hidden="true"></span>';const art=b.lastElementChild;if(key==='color')source.querySelectorAll('#tray .bottle').forEach((b,i)=>{if(i<3)art.append(b.cloneNode(true));});if(key==='nail')art.innerHTML=['natural','almond','stiletto'].map(nailSilhouette).join('');if(key==='objects')for(const shape of ['heart','statement','pearl'])art.append(previewCanvas({type:'gem',shape,color:'#b97583'}));if(key==='tools')tools.querySelectorAll('.tool').forEach((b,i)=>{if(i<3)art.append(b.cloneNode(true));});art.querySelectorAll('button').forEach(b=>{const sample=document.createElement('span');sample.className=b.className;sample.style.cssText=b.style.cssText;sample.innerHTML=b.innerHTML;b.replaceWith(sample);});b.onclick=()=>open(key);nav.append(b);}
 const bar=document.createElement('div');bar.className='toolbox-bar';const back=document.createElement('button');back.textContent='← toolbox';back.onclick=()=>open('home');const shut=document.createElement('button');shut.textContent='close case ↓';shut.onclick=close;bar.append(back,shut);bench.append(toggle,bar,nav,center);root.append(bench);source.hidden=true;
 const indicator=document.createElement('button');indicator.id='active-tool';indicator.setAttribute('aria-label','Active tool — open toolbox');indicator.onclick=()=>open(root.dataset.tool==='pick'?'objects':'tools');root.append(indicator);
 const parking=document.createElement('div');parking.hidden=true;bench.append(parking);parking.append(tools,transfer);
 function set(isOpen,home=false){root.classList.toggle('workbench-open',isOpen);bench.dataset.open=String(isOpen);bench.dataset.home=String(home);toggle.setAttribute('aria-expanded',String(isOpen));toggle.inert=isOpen;toggle.setAttribute('aria-hidden',String(isOpen));}
 return {tools,transfer,indicator,parkTools(){parking.append(tools,transfer);},set};
}
